import {seedItems,seedMissions} from '../modules/content.js';import{localCatalog,escapeHTML as e}from'../modules/state.js';import{getFirebaseConfig}from'../config/firebase-config.js';import * as cloud from '../firebase/service.js';
const $=s=>document.querySelector(s);let admin=false,user=null,tab='items';let items=localCatalog(seedItems,'items'),missions=localCatalog(seedMissions,'missions');const feedback=s=>$('#feedback').textContent=s;
function status(){$('#adminStatus').textContent=admin?'ผู้ดูแลระบบ · '+user.displayName:'โหมดเตรียมเนื้อหาในอุปกรณ์';$('#notice').textContent=admin?'แก้ไขเนื้อหาใน Firestore ของโครงการที่เชื่อมต่อ คะแนนจะคำนวณโดย Firestore Security Rules เท่านั้น':getFirebaseConfig()?'เข้าสู่ระบบบัญชีที่มี Custom Claim admin เพื่อจัดการข้อมูลคลาวด์ ขณะนี้แก้ไขได้เฉพาะชุดเนื้อหาในเบราว์เซอร์นี้':'ยังไม่ได้เชื่อมต่อ Firebase คุณสามารถเตรียมเนื้อหาในอุปกรณ์ได้ และตั้งค่า Firebase เพื่อเปิดสมาชิก การบันทึกคลาวด์ และผู้ดูแลจริง';}
async function draw(){feedback('');if(tab==='settings'){$('#adminContent').innerHTML=`<section class="admin-card"><h2>เชื่อมต่อ Firebase ของโรงเรียน</h2><p class="reading">วาง Firebase Web Config แบบ JSON จาก Project settings → Your apps ข้อมูลนี้เป็นค่าฝั่งเว็บ ห้ามใส่ Service Account หรือ Private Key</p><textarea id="config" class="settings-field" placeholder='{"apiKey":"…","authDomain":"…","projectId":"…","appId":"…"}'>${e(getFirebaseConfig()?JSON.stringify(getFirebaseConfig(),null,2):'')}</textarea><button class="primary" id="saveConfig">บันทึกและเชื่อมต่อ</button><div class="admin-notice">การตั้งค่านี้มีผลเฉพาะเบราว์เซอร์ปัจจุบัน สำหรับใช้งานทั้งโรงเรียนให้ใส่ Web Config ใน js/config/firebase-config.js แล้ว deploy Firebase Hosting ตาม README<br>ต้องเปิด Google Sign-in, เพิ่ม Authorized domain, deploy firestore.rules ก่อนใช้งานจริง</div></section>`;$('#saveConfig').onclick=()=>{try{const c=JSON.parse($('#config').value);if(!c.apiKey||!c.projectId||!c.authDomain||!c.appId)throw Error('ต้องมี apiKey, projectId, authDomain และ appId');if(c.private_key||c.type==='service_account')throw Error('ห้ามใช้ Service Account ในเว็บ');localStorage.setItem('ca-firebase-config',JSON.stringify(c));location.reload()}catch(err){feedback('บันทึกไม่ได้: '+err.message)}};return}
if(tab==='users'){if(!admin){$('#adminContent').innerHTML='<div class="admin-card"><h2>ข้อมูลผู้เล่นเป็นข้อมูลส่วนตัว</h2><p class="reading">เข้าสู่ระบบบัญชีผู้ดูแลที่กำหนดไว้ใน admin_settings/access เพื่อดูรายชื่อ คะแนน และความคืบหน้าจาก Firestore</p></div>';return}try{const [users,progress,inventory,leaders]=await Promise.all(['users','player_progress','player_inventory','leaderboard'].map(cloud.getCatalog));$('#adminContent').innerHTML=`<div class="admin-card"><h2>ผู้เล่น ${users.length} คน</h2><table><tr><th>ผู้เล่น / UID</th><th>คะแนน</th><th>ไอเทม</th><th>ตำแหน่งล่าสุด</th></tr>${users.map(u=>{const p=progress.find(p=>p.id===u.id)?.position;return`<tr><td>${e(u.displayName)}<br><small>${e(u.id)}</small></td><td>${leaders.find(l=>l.id===u.id)?.score||0}</td><td>${inventory.find(i=>i.id===u.id)?.ids?.length||0}/12</td><td>${p?e(p.x.toFixed(1)+', '+p.z.toFixed(1)):'—'}</td></tr>`}).join('')}</table></div>`}catch(err){feedback(err.message)}return}
const list=tab==='items'?items:missions;$('#adminContent').innerHTML=`<div class="section-top"><h2>${tab==='items'?'ไอเทมและบทเรียน':'ภารกิจและรางวัล'} (${list.length})</h2><div><button id="export">ดาวน์โหลด JSON ↓</button>　<button id="seed">${admin?'อัปโหลดชุดเริ่มต้น':'คืนค่าชุดเริ่มต้น'}</button></div></div><div class="admin-grid">${list.map((r,i)=>`<form class="admin-card" data-id="${e(r.id)}"><small>${e(r.id)}</small>${tab==='items'?`<label>ชื่อไอเทม<input name="name" required value="${e(r.name)}" maxlength="100"></label><label>หัวข้อความรู้<input name="title" required value="${e(r.title)}" maxlength="160"></label><label>เนื้อหา<textarea name="body" required maxlength="4000">${e(r.body)}</textarea></label><label>ชวนคิด<textarea name="challenge" required maxlength="1000">${e(r.challenge)}</textarea></label><label>คะแนน<input type="number" name="points" min="0" max="1000" required value="${r.points}"></label>`:`<label>ชื่อภารกิจ<input name="name" value="${e(r.name)}" required></label><label>คำอธิบาย<input name="description" value="${e(r.description)}" required></label><label>ไอเทมที่ต้องเก็บ<input name="required" type="number" min="1" max="12" required value="${r.required}"></label><label>รางวัล XP<input name="reward" type="number" min="0" max="5000" required value="${r.reward}"></label>`}<button class="primary">บันทึก${admin?'คลาวด์':'ในอุปกรณ์'}</button></form>`).join('')}</div>`;
document.querySelectorAll('form').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const old=list.find(x=>x.id===f.dataset.id),record={...old};for(const [key,value]of new FormData(f))record[key]=['points','reward','required'].includes(key)?Number(value):value;try{if(admin)await cloud.saveRecord(tab,record.id,record);list[list.indexOf(old)]=record;localStorage.setItem('ca-'+tab,JSON.stringify(list));feedback('✓ บันทึกแล้ว — เปิดเกมใหม่เพื่อใช้เนื้อหาล่าสุด');f.querySelector('button').textContent='✓ บันทึกแล้ว'}catch(err){feedback('บันทึกไม่สำเร็จ: '+err.message)}});
$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(list,null,2)],{type:'application/json'}));a.download=tab+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#seed').onclick=async()=>{try{const seed=tab==='items'?seedItems:seedMissions;if(admin){for(const r of seed)await cloud.saveRecord(tab,r.id,r)}else localStorage.removeItem('ca-'+tab);if(tab==='items')items=seedItems.map(x=>({...x}));else missions=seedMissions.map(x=>({...x}));await draw();feedback('✓ เตรียมชุดเริ่มต้นเรียบร้อย')}catch(err){feedback(err.message)}}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;draw()});$('#adminLogin').onclick=async()=>{try{user=await cloud.loginGoogle();admin=await cloud.isAdmin(user);if(admin){[items,missions]=await Promise.all([cloud.getCatalog('items'),cloud.getCatalog('missions')]);if(!items.length)items=seedItems;if(!missions.length)missions=seedMissions}status();draw();if(!admin)feedback('บัญชีนี้ยังไม่มีสิทธิ์ผู้ดูแล กรุณาเพิ่มอีเมลที่ยืนยันแล้วใน admin_settings/access ผ่าน Firebase Console')}catch(err){feedback(err.message)}};status();if(location.hash==='#settings')tab='settings';draw();if(getFirebaseConfig())cloud.observeUser(async u=>{if(!u)return;user=u;admin=await cloud.isAdmin(u);if(admin){const[a,b]=await Promise.all([cloud.getCatalog('items'),cloud.getCatalog('missions')]);if(a.length)items=a;if(b.length)missions=b}status();draw()}).catch(err=>feedback(err.message));
